# Surah Hud (chapter 11) — part 4: ayat 31-40 (IDs 1504-1513)
SURAH = 11

ENTRIES = {
1504: (
"اور — میں — تم — سے — یہ نہیں کہتا — کہ میرے پاس — اللہ — کے خزانے — ہیں — اور — نہ — میں — غیب — جانتا ہوں — اور — نہ — یہ — کہتا ہوں — کہ — میں فرشتہ — ہوں — اور — نہ — ان — کے لیے — جنہیں تمہاری — نظریں — حقیر — سمجھتی ہیں — یہ — کہتا ہوں — کہ — اللہ — انہیں — کوئی خیر — نہیں دے گا — اللہ — ان — کے — دلوں — میں جو ہے — اس — کو خوب جانتا ہے — بے شک — میں — اس — صورت — میں — ظالموں — میں سے ہوں",
"""۱۔ نوحؑ — بشر ہیں؛ نہ — خزانے والے، نہ غیب دان، نہ فرشتہ۔
۲۔ ’’وَلَا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلَا أَعْلَمُ الْغَيْبَ وَلَا أَقُولُ إِنِّي مَلَكٌ وَلَا أَقُولُ لِلَّذِينَ تَزْدَرِي أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ اللَّهُ خَيْرًا اللَّهُ أَعْلَمُ بِمَا فِي أَنفُسِهِمْ إِنِّي إِذًا لَّمِنَ الظَّالِمِينَ‘‘ — اور — میں — تم — سے — یہ نہیں کہتا — کہ میرے پاس — اللہ — کے خزانے — ہیں — اور — نہ — میں — غیب — جانتا ہوں — اور — نہ — یہ — کہتا ہوں — کہ — میں فرشتہ — ہوں — اور — نہ — ان — کے لیے — جنہیں تمہاری — نظریں — حقیر — سمجھتی ہیں — یہ — کہتا ہوں — کہ — اللہ — انہیں — کوئی خیر — نہیں دے گا — اللہ — ان — کے — دلوں — میں جو ہے — اس — کو خوب جانتا ہے — بے شک — میں — اس — صورت — میں — ظالموں — میں سے ہوں — یعنی نوحؑ فرماتے ہیں — میرے پاس — اللہ کے خزانے — نہیں — میں غیب نہیں جانتا — میں فرشتہ — نہیں — اور میں — مفلس مؤمنوں کے بارے میں — یہ نہیں کہتا — کہ اللہ انہیں — خیر نہیں دے گا — اللہ — ان کے دلوں — کو جانتا ہے؛ اگر ایسا — کہوں تو ظالموں — میں سے ہو جاؤں۔
۳۔ عملی سبق: کامل — علم — صرف — اللہ کا ہے؛ کسی — بھی شخصیت — کو — خدا نہ بناؤ۔"""
),
1505: (
"انہوں نے — کہا — اے نوحؑ — تم نے — ہمیں — شدید — جھگڑا — کیا — پس — اس — کو لاؤ — جس — کا — تم — ہمیں وعدہ — دیتے ہو — اگر — تم سچے ہو",
"""۱۔ قومِ نوحؑ — جھگڑا — کرتی ہے — عذاب کا مطالبہ۔
۲۔ ’’قَالُوا يَا نُوحُ قَدْ جَادَلْتَنَا فَأَكْثَرْتَ جِدَالَنَا فَأْتِنَا بِمَا تَعِدُنَا إِن كُنتَ مِنَ الصَّادِقِينَ‘‘ — انہوں نے — کہا — اے نوحؑ — تم نے — ہمیں — شدید — جھگڑا — کیا — پس — اس — کو لاؤ — جس — کا — تم — ہمیں وعدہ — دیتے ہو — اگر — تم سچے ہو — یعنی انہوں نے کہا — اے نوحؑ — تم نے ہمیں — کافی جھگڑا — کیا — پس — اس عذاب — کو لاؤ — جس کا تم وعدہ — دے رہے ہو — اگر تم سچے ہو۔
۳۔ عملی سبق: حق — مذاق نہیں — ہے؛ وقت — پر — سزا — آئے گی۔"""
),
1506: (
"انہوں نے — کہا — بے شک — اللہ — ہی — اسے — تمہارے پاس — لائے گا — اگر — وہ — چاہے — اور — تم — عاجز — نہیں کر سکتے",
"""۱۔ عذاب — اللہ کے — اذن سے — آتا ہے۔
۲۔ ’’قَالَ إِنَّمَا يَأْتِيكُم بِهِ اللَّهُ إِن شَاءَ وَمَا أَنتُم بِمُعْجِزِينَ‘‘ — انہوں نے — کہا — بے شک — اللہ — ہی — اسے — تمہارے پاس — لائے گا — اگر — وہ — چاہے — اور — تم — عاجز — نہیں کر سکتے — یعنی نوحؑ نے کہا — اللہ — ہی — اسے لائے گا — اگر چاہے؛ تم — اللہ — کو — عاجز — نہیں کر سکتے۔
۳۔ عملی سبق: عذاب کا وقت — اللہ — طے کرتا ہے؛ کوئی عاجز — نہیں کر سکتا۔"""
),
1507: (
"اور — جب — اللہ — تم — کو — گمراہ کرنا چاہتا ہو — تو — میری نصیحت — تم — کو — فائدہ — نہیں دے گی — اگرچہ — میں — تمہیں نصیحت — کرنا چاہوں — وہ — تمہارا — رب ہے — اور — اسی کی طرف — تم — لوٹ — جاؤ گے",
"""۱۔ اگر اللہ — گمراہ کرنا چاہتا ہو — تو نصیحت بے فائدہ۔
۲۔ ’’وَلَا يَنفَعُكُمْ نُصْحِي إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ اللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ‘‘ — اور — جب — اللہ — تم — کو — گمراہ کرنا چاہتا ہو — تو — میری نصیحت — تم — کو — فائدہ — نہیں دے گی — اگرچہ — میں — تمہیں نصیحت — کرنا چاہوں — وہ — تمہارا — رب ہے — اور — اسی کی طرف — تم — لوٹ — جاؤ گے — یعنی اگر اللہ — تمہیں گمراہ — کرانا چاہتا ہے — تو میری نصیحت — تمہیں فائدہ نہیں دے گی؛ وہ تمہارا رب — ہے — اور اسی — کی طرف — تم لوٹو گے۔
۳۔ عملی سبق: ہدایت اور گمراہی — اللہ کے ہاتھ میں؛ نفس کی فریاد — اس سے مانگو۔"""
),
1508: (
"یا — وہ — کہتے ہیں — اس — نے — اس — کو — گھڑ لیا ہے — کہدو — اگر — میں — نے — اسے — گھڑا — ہے — تو — میرا جرم — میرے — اوپر ہے — اور — میں — اس جرم — سے بری ہوں — جو — تم — کرتے ہو",
"""۱۔ فطرت — سب کو معلوم ہے؛ جھٹلانے والوں کی آنکھیں — بند ہیں۔
۲۔ ’’أَمْ يَقُولُونَ افْتَرَاهُ قُلْ إِنِ افْتَرَيْتُهُ فَعَلَيَّ إِجْرَامِي وَأَنَا بَرِيءٌ مِّمَّا تُجْرِمُونَ‘‘ — یا — وہ — کہتے ہیں — اس — نے — اس — کو — گھڑ لیا ہے — کہدو — اگر — میں — نے — اسے — گھڑا — ہے — تو — میرا جرم — میرے — اوپر ہے — اور — میں — اس جرم — سے بری ہوں — جو — تم — کرتے ہو — یعنی اگر میں نے — قرآن — گھڑا ہے — تو میرا جرم — میرے اوپر ہے — اور میں — تمہارے — جرم سے بری ہوں۔
۳۔ عملی سبق: ہر شخص — اپنے — جرم کا — بوجھ خود — اٹھائے گا۔"""
),
1509: (
"اور — نوحؑ — کی طرف — وحی کی گئی — کہ — آپ کی قوم — میں سے — سوائے — ان کے جو — پہلے ہی — ایمان — لا چکے — کوئی — ایمان — نہیں لائے گا — پس — آپ — اس — پر رنج — نہ کریں — جو — وہ — کرتے ہیں",
"""۱۔ نوحؑ — کو بتایا گیا — قوم — میں سے زیادہ لوگ ایمان — نہیں لائیں گے۔
۲۔ ’’وَأُوحِيَ إِلَىٰ نُوحٍ أَنَّهُ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ آمَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا يَفْعَلُونَ‘‘ — اور — نوحؑ — کی طرف — وحی کی گئی — کہ — آپ کی قوم — میں سے — سوائے — ان کے جو — پہلے ہی — ایمان — لا چکے — کوئی — ایمان — نہیں لائے گا — پس — آپ — اس — پر رنج — نہ کریں — جو — وہ — کرتے ہیں — یعنی آپؑ کی قوم — میں سے — پہلے سے ایمان لانے والوں کے سوا — کوئی — ایمان — نہیں لائے گا — پس آپ — اس پر غمگین — نہ ہوں — جو وہ کرتے ہیں۔
۳۔ عملی سبق: ڈیوٹی — کرو؛ نتیجہ — اللہ — کے ہاتھ میں — ہے۔"""
),
1510: (
"اور — آپؑ — کشتی — بنائیں — ہماری — نگرانی — میں — اور — ہماری — وحی — کے — مطابق — اور — آپؑ — ظالم لوگوں — کے بارے میں — مجھ سے بات — نہ کریں — بے شک — وہ — ڈبو دیے — جانے والے — ہیں",
"""۱۔ کشتی بنانے کا — حکم — اللہ کی نگرانی میں۔
۲۔ ’’وَاصْنَعِ الْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَاطِبْنِي فِي الَّذِينَ ظَلَمُوا إِنَّهُم مُّغْرَقُونَ‘‘ — اور — آپؑ — کشتی — بنائیں — ہماری — نگرانی — میں — اور — ہماری — وحی — کے — مطابق — اور — آپؑ — ظالم لوگوں — کے بارے میں — مجھ سے بات — نہ کریں — بے شک — وہ — ڈبو دیے — جانے والے — ہیں — یعنی ہماری نگرانی اور وحی کے مطابق — کشتی بنائیں — اور ظالموں کے بارے میں میرے پاس — بات نہ کریں؛ وہ — ڈبو دیے جانے والے — ہیں۔
۳۔ عملی سبق: اللہ کا حکم — آنے پر — عمل کرو؛ بحث — چھوڑ دو۔"""
),
1511: (
"اور — وہ — کشتی بناتے رہے — اور — جب — بھی — ان — کی — قوم کے سردار — ان — کے — پاس سے — گزرتے — تو — ان — پر — ہنستے — انہوں نے — کہا — اگر — تم — ہم — پر ہنستے ہو — تو — ہم — بھی — تم — پر ہنسیں گے — جس طرح — تم ہنستے ہو",
"""۱۔ قوم — کشتی — بنانے پر — مسخرہ — اڑاتی ہے۔
۲۔ ’’وَيَصْنَعُ الْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌ مِّن قَوْمِهِ سَخِرُوا مِنْهُ قَالَ إِن تَسْخَرُوا مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ‘‘ — اور — وہ — کشتی بناتے رہے — اور — جب — بھی — ان — کی — قوم کے سردار — ان — کے — پاس سے — گزرتے — تو — ان — پر — ہنستے — انہوں نے — کہا — اگر — تم — ہم — پر ہنستے ہو — تو — ہم — بھی — تم — پر ہنسیں گے — جس طرح — تم ہنستے ہو — یعنی نوحؑ — کشتی بنا رہے تھے — قوم — مسخرہ — اڑا رہی تھی؛ نوحؑ نے کہا — تم ہم — پر ہنستے ہو — تو ہم بھی — تم — پر — ہنسیں گے — جیسے تم ہنستے ہو۔
۳۔ عملی سبق: مسخرا — اڑانے والے — وقت کے ساتھ — خود — شرمندہ — ہوتے ہیں۔"""
),
1512: (
"پس — عنقریب — تم — جانو گے — کہ — کس کے پاس — ایسا عذاب — آتا ہے — جو — اسے رسوا — کر دے — اور — کس پر — دائمی عذاب — اترتا ہے",
"""۱۔ عذاب — اور ابدی سزا — عنقریب ظاہر ہو گی۔
۲۔ ’’فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ‘‘ — پس — عنقریب — تم — جانو گے — کہ — کس کے پاس — ایسا عذاب — آتا ہے — جو — اسے رسوا — کر دے — اور — کس پر — دائمی عذاب — اترتا ہے — یعنی عنقریب — تم جانو گے — کس — پر — ایسا عذاب آتا ہے — جو اسے رسوا کر دے — اور کس — پر — دائمی عذاب — پڑتا ہے۔
۳۔ عملی سبق: انجام — عنقریب — کھل کر — آئے گا۔"""
),
1513: (
"یہاں تک کہ — جب — ہمارا حکم — آ گیا — اور — تنور — ابل پڑا — ہم — نے — کہا — اس میں — ہر — جوڑے — میں سے — دو — یعنی — ایک — نر اور ایک مادہ — سوار کرو — اور — اپنے اہل — کو — بھی — سوائے — ان — کے جن — پر — پہلے — بات پڑی — اور — ان — لوگوں کو — جو — ایمان — لائے — اور — اس — کے ساتھ — بہت کم — لوگ ایمان لائے",
"""۱۔ تنور ابلنے — سے عذاب کا آغاز — کشتی میں — جوڑے اور اہلِ ایمان — سوار کیے گئے۔
۲۔ ’’حَتَّىٰ إِذَا جَاءَ أَمْرُنَا وَفَارَ التَّنُّورُ قُلْنَا احْمِلْ فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ الْقَوْلُ وَمَنْ آمَنَ وَمَا آمَنَ مَعَهُ إِلَّا قَلِيلٌ‘‘ — یہاں تک کہ — جب — ہمارا حکم — آ گیا — اور — تنور — ابل پڑا — ہم — نے — کہا — اس میں — ہر — جوڑے — میں سے — دو — یعنی — ایک — نر اور ایک مادہ — سوار کرو — اور — اپنے اہل — کو — بھی — سوائے — ان — کے جن — پر — پہلے — بات پڑی — اور — ان — لوگوں کو — جو — ایمان — لائے — اور — اس — کے ساتھ — بہت کم — لوگ ایمان لائے — یعنی جب — اللہ کا حکم آیا اور — تنور — ابل پڑا — نوحؑ کو — ہر جوڑے — میں سے دو — اور اپنے اہل — اور — ایمان — لائے ہوئے لوگ — سوار کرنے کا حکم — ملا؛ ایمان لانے والے — بہت کم — تھے۔
۳۔ عملی سبق: ایمان — والوں — کی تعداد — کم ہو — تو — بھی — اللہ کے ساتھ — رہو۔"""
),
}
